 heading('History'),dict(figure('isaac-newton-source','Isaac Newton','Original source portrait of Isaac Newton'),displayWidth=110),dict(figure('gw-leibniz-source','G.W Leibniz','Original source portrait of G.W. Leibniz'),displayWidth=110),
